begin;

-- DRULE-002 Layer-0 successor coverage checkpoint, 2026-10-27.
-- Classifies Sections 1-28 without inventing missing 2025 clause text.
-- This changes reconciliation metadata only. It does not activate rules,
-- promote candidates, close archaeology, or change production authority.

with project as (
  select id from comind_pm.pm_projects where project_key = 'COMIND'
), source_document as (
  select d.id
  from comind_pm.pm_rule_source_documents d
  join project p on p.id = d.project_id
  where d.source_system = 'gdrive'
    and d.source_ref = 'https://drive.google.com/file/d/16Yeim-s_mujVYWIgTmLeabFcgYMHni1l/view'
), coverage(section_number, coverage_state, rationale, evidence_refs, next_action) as (
  values
  (1, 'modern_coverage_adequate', 'Current authority tiers, governance precedence, fail-closed ambiguity handling, epistemic gates, and human institutional authority materially cover the historical constitutional-priority family.', jsonb_build_array('CAND-L0-CONST-001','RULE-GOV-001','RULE-GOV-002','RULE-GOV-003','RULE-GP-005','RULE-EPI-004'), 'Reconcile historical terminology and lineage without creating a duplicate constitutional authority layer.'),
  (2, 'modern_coverage_adequate', 'Current C0-C4 authority boundaries, Foundry capability grants, explicit human accountability, and least-privilege design materially cover identity, role, and access-control governance.', jsonb_build_array('RULE-AUTH-001','RULE-GP-005','docs/governance/iso/AIMS-SCOPE-DRAFT.md','docs/governance/iso/AIMS-CONTROL-EVIDENCE-MATRIX.md'), 'Retain lower-authority historical clinical-role and self-escalation proposals for scoped reconciliation only.'),
  (3, 'modern_governance_gap', 'CoMind recognizes data sensitivity and classification as in scope, but the current AIMS applicability view explicitly records gaps for governing data resources, sensitivity, allowed use, data requirements, and labeling/bias preparation. No active Durable RuleBook classification taxonomy or handling contract closes this family.', jsonb_build_array('docs/governance/iso/AIMS-SCOPE-DRAFT.md','docs/governance/iso/AIMS-STATEMENT-OF-APPLICABILITY-PROVISIONAL.md','NIST-SP-800-60-Rev2-IWD'), 'Define and approve a canonical data-classification and tagging contract tied to handling, access, retention, external transfer, logging, and testable enforcement.'),
  (4, 'modern_coverage_partial', 'Raw-secret handling and provider credential boundaries exist, but CoMind lacks a complete current cryptographic-key lifecycle and cryptographic-baseline governance contract covering inventory, rotation, compromise, recovery, algorithm policy, and retirement.', jsonb_build_array('RULE-SEC-001','docs/architecture/provider-independence-and-model-arbitration.md','NIST-SP-800-57-Part1-Rev5'), 'Create a security reconciliation case for key lifecycle and cryptographic baseline without duplicating existing secret-handling rules.'),
  (5, 'modern_coverage_adequate', 'Current memory governance prohibits silent durable edits and requires inspectable review and explicit disposition. The historical approval candidate has already been promoted into canonical split rules.', jsonb_build_array('RULE-MEM-004','RULE-MEM-005','CAND-MEM-APPROVAL-001'), 'Preserve historical lineage and continue validating implementation coverage; no new global memory-write rule is required from Layer-0 archaeology.'),
  (6, 'modern_coverage_partial', 'Governed retrieval, private-reader patterns, and access-bound architecture exist, but the general rule that retrieval must enforce requester authority and policy scope remains an unpromoted historical candidate rather than a canonical RuleBook control.', jsonb_build_array('CAND-L0-PROP-RETRIEVE-001','docs/architecture/chist-a01-personal-analytics.md','docs/governance/iso/AIMS-AI-POLICY-DRAFT.md'), 'Reconcile retrieval authorization into a canonical cross-system rule, then map memory, conversation-history, research, and connector readers to it.'),
  (7, 'modern_coverage_partial', 'Correction and invalidation lineage are strongly governed, but selective forgetting remains unresolved against privacy, legal deletion, evidence retention, and audit-preservation duties.', jsonb_build_array('RULE-RPDA-009','CAND-DATA-SOFTDELETE-001','RC-SOFTDELETE-001','docs/governance/iso/AIMS-CONTROL-EVIDENCE-MATRIX.md'), 'Resolve deletion authority and retention precedence by data class and legal basis before promoting a global forget/delete rule.'),
  (8, 'modern_coverage_adequate', 'Current epistemic and RPDA controls explicitly preserve premise validation, contradictions, competing models, correction history, and non-destructive conflict handling.', jsonb_build_array('RULE-EPI-004','RULE-RPDA-006','CAND-L0-PROP-CONTRA-001'), 'Map historical wording to current epistemic controls and retain any narrower corroboration proposal only if it adds non-duplicative value.'),
  (9, 'modern_coverage_adequate', 'Current provenance, raw-observation immutability, correction lineage, evidence-state, confidence, and observable-evidence controls materially cover the historical provenance and truth-scoring family.', jsonb_build_array('RULE-RPDA-004','RULE-RPDA-007','RULE-EVID-005','CAND-L0-PROP-PROV-001','CAND-L0-PROP-HASH-001'), 'Reconcile optional integrity-hash specialization separately; do not duplicate existing provenance authority.'),
  (10, 'modern_coverage_partial', 'CoMind now has an AIMS scope, standards applicability register, certification-claim controls, and framework-version governance, but legal and regulatory applicability for actual markets, geographies, health use cases, HIPAA, SOC 2, and similar obligations remains intentionally unresolved.', jsonb_build_array('docs/governance/iso/AIMS-SCOPE-DRAFT.md','docs/governance/iso/STANDARDS-APPLICABILITY-REGISTER.md','docs/governance/iso/AIMS-AI-POLICY-DRAFT.md'), 'Create an applicability-driven compliance register as products, markets, data classes, and contractual obligations become concrete; do not claim HIPAA, SOC 2, ISO, or other conformity without evidence.'),
  (11, 'modern_coverage_partial', 'Prompt injection, goal hijack, sensitive disclosure, and agentic misuse are explicitly recognized in the AIMS risk and policy architecture, and fail-closed broker patterns exist. The controlled evidence matrix still rates prompt/output and agentic security as partial because threat-model coverage, adversarial tests, and traceable mitigations are incomplete.', jsonb_build_array('docs/governance/iso/AIMS-RISK-AND-IMPACT-REGISTER.md','docs/governance/iso/AIMS-CONTROL-EVIDENCE-MATRIX.md','docs/governance/iso/AIMS-AI-POLICY-DRAFT.md','OWASP-LLM01-2025','OWASP-LLM02-2025'), 'Convert recognized risk into approved cross-system trust-boundary rules and verified prompt-injection, tool-misuse, and exfiltration controls.'),
  (12, 'modern_coverage_adequate', 'Foundry and agent governance provide explicit identity, capability, task authority, bounded deliberation, defined terminal states, and cross-domain coordination without granting privilege from helper recommendations.', jsonb_build_array('RULE-AGENT-001','RULE-FND-005','RULE-FND-008','RULE-FND-009','RULE-FND-010'), 'Continue implementation evidence and role-specific mapping; no Layer-0 replacement rule is needed.'),
  (13, 'modern_governance_gap', 'CoMind has component-specific network configurations, but no canonical network and egress governance contract defines destination authorization, information-flow restrictions, service identity, outbound transfer policy, logging, and deny/fail behavior across agents, tools, connectors, and services. The AIMS applicability view marks environment governance as a gap.', jsonb_build_array('docs/governance/iso/AIMS-STATEMENT-OF-APPLICABILITY-PROVISIONAL.md','NIST-SP-800-207','NIST-SP-800-207A','NIST-SP-800-53-AC4'), 'Define a canonical network and egress control contract, then map provider calls, connectors, browser/server boundaries, data export, and service-to-service traffic to enforceable policies.'),
  (14, 'modern_coverage_adequate', 'Current recovery, rollback, continuity, bounded retry, safe degradation, backup tooling, and recovery-evidence patterns materially cover storage, backup, and recovery governance even though individual systems retain implementation-specific proof obligations.', jsonb_build_array('RULE-FND-004','CAND-OPS-RESILIENCE-001','RULE-CONT-001','sdn/production/pgbackrest.conf'), 'Keep backup restoration and recovery proof system-specific and evidence-backed; do not infer production effectiveness from repository configuration alone.'),
  (15, 'modern_coverage_partial', 'Founder override authority and fail-closed governance ambiguity are explicit, but CoMind lacks a formal operational break-glass contract for emergency identity, temporary privilege, reason capture, time bounds, independent review, revocation, and post-event evidence.', jsonb_build_array('RULE-AUTH-002','RULE-GOV-003','NIST-SP-800-53-AC2','NIST-SP-800-53-AC3-10'), 'Specify a bounded break-glass procedure that cannot silently become a standing privilege path.'),
  (16, 'modern_coverage_adequate', 'Current migration, testing, evidence, source reconciliation, and staged-maturity controls materially cover versioning, change control, verification, and Test-first promotion.', jsonb_build_array('RULE-DB-002','RULE-DB-003','RULE-DB-005','RULE-EVID-001','CAND-PROV-SOT-001'), 'Continue exact-head CI and deployment evidence; no Layer-0 duplicate control is needed.'),
  (17, 'modern_governance_gap', 'Cross-tenant and cross-project leakage is recognized as a material risk, but tenant-session enforcement remains an outstanding critical item and current database evidence includes broad-access/RLS gaps. There is no canonical end-to-end tenancy-isolation control contract covering identity propagation, database policy, service scope, and isolation testing.', jsonb_build_array('docs/governance/iso/AIMS-RISK-AND-IMPACT-REGISTER.md','docs/governance/iso/AIMS-CONTROL-EVIDENCE-MATRIX.md','db/sql/v2/12_enterprise_checklist.sql','Supabase-RLS-guidance','NIST-SP-800-207A'), 'Define canonical tenant/project isolation semantics and prove them across database, service, agent, connector, cache, retrieval, and export boundaries before multi-tenant production claims.'),
  (18, 'modern_coverage_adequate', 'Current observability governance requires visible delegated work, durable status, anomaly monitoring direction, terminal conditions, evidence links, and monitoring of failures, drift, cost, and control degradation. The AIMS applicability view records isolated verification for operational monitoring.', jsonb_build_array('RULE-OPS-001','CAND-OBS-AUTOWATCH-001','docs/governance/iso/AIMS-STATEMENT-OF-APPLICABILITY-PROVISIONAL.md'), 'Reconcile Auto-Watch naming and system-wide coverage without duplicating module-specific observability contracts.'),
  (19, 'modern_coverage_partial', 'Continuity architecture materially covers export, restoration, migration, successor handoff, and portability, but data-residency, jurisdiction, transfer-location, and residency-exception governance is not yet complete.', jsonb_build_array('RULE-CONT-004','RULE-CONT-005','docs/governance/iso/AIMS-SCOPE-DRAFT.md'), 'Add residency and cross-jurisdiction transfer applicability only when data classes, providers, markets, and legal obligations are known.'),
  (20, 'modern_coverage_adequate', 'Approved IP and licensing controls require exact license and transitive review, unresolved-license escalation, version-specific exceptions, non-code artifact review, and proprietary-IP protection.', jsonb_build_array('RULE-IP-001','RULE-IP-002','RULE-IP-003','RULE-IP-004','RULE-IP-006','RULE-IP-008','RULE-IP-009'), 'Maintain evidence and supplier/version linkage; no Layer-0 replacement control is needed.'),
  (21, 'modern_coverage_adequate', 'Current supply-chain controls cover dependency inventories, pull-request/release scanning, unresolved-license blocking, upgrade drift detection, and commercialization diligence.', jsonb_build_array('RULE-SUPPLY-001','RULE-SUPPLY-002','RULE-SUPPLY-003','RULE-SUPPLY-004','RULE-SUPPLY-005'), 'Extend the same governed evidence model to models, datasets, plugins, and non-code suppliers as those become material.'),
  (22, 'modern_coverage_adequate', 'Current epistemic, RPDA, Helper Matrix, SEAL, and causal-governance work separates premise validation, evidence quality, revision loops, purpose lineage, and epistemic object types.', jsonb_build_array('RULE-EPI-004','RULE-RPDA-001','RULE-RPDA-003'), 'Preserve explicit lineage from older named reasoning systems without restoring obsolete mechanisms as authority.'),
  (23, 'modern_coverage_adequate', 'Continuity and RPDA explicitly govern temporal validity, drift, terminology mapping, correction history, stable versus evolvable contracts, and identity/context consistency.', jsonb_build_array('RULE-RPDA-005','RULE-CONT-004','RULE-GP-004'), 'Continue temporal/identity proof at implementation boundaries; no duplicate Layer-0 rule is required.'),
  (24, 'modern_coverage_partial', 'Proportional governance, human accountability, risk-impact structure, and fairness/human-rights flags exist, but individual/group impact controls are still proposed and data preparation/labeling/bias governance remains a recorded gap.', jsonb_build_array('RULE-GP-001','RULE-GP-005','docs/governance/iso/AIMS-RISK-AND-IMPACT-REGISTER.md','docs/governance/iso/AIMS-STATEMENT-OF-APPLICABILITY-PROVISIONAL.md'), 'Turn fairness and sensitive-use risk themes into scoped impact criteria, data/bias controls, review triggers, and evidence before any high-consequence use.'),
  (25, 'modern_coverage_adequate', 'Current resilience architecture and implementation contracts require bounded retries, explicit failure classes, recovery paths, stopping conditions, visible degradation, and cost/resource boundaries.', jsonb_build_array('CAND-OPS-RESILIENCE-001','RULE-FIN-002','RULE-FIN-003','RULE-OPS-002'), 'Promote only the non-duplicative reusable resilience portions after reconciliation; keep service-specific limits configurable.'),
  (26, 'modern_coverage_adequate', 'Current epistemic controls prohibit unsupported certainty, require multi-source verification for high-impact claims, validate premises, and require abstention when verification is insufficient.', jsonb_build_array('RULE-EPI-002','RULE-EPI-003','RULE-EPI-004','RULE-EPI-006'), 'Map misinformation-defense lineage to epistemic integrity rather than creating a separate truth authority.'),
  (27, 'modern_coverage_partial', 'Research write-through, provenance, archive preservation candidates, and audit minimization exist, but privacy classification, minimization, retention, legal hold, disposal, and deletion obligations remain incomplete as a unified control family.', jsonb_build_array('RULE-EVID-002','RULE-DATA-001','CAND-DATA-ARCHIVE-001','CAND-DATA-INGEST-001','docs/governance/iso/AIMS-CONTROL-EVIDENCE-MATRIX.md'), 'Unify logging/research evidence with privacy-by-data-class retention and deletion rules without storing unnecessary sensitive content.'),
  (28, 'modern_coverage_adequate', 'Current authority, governance, Foundry, and Governing Principle controls preserve explicit human accountability, scoped ownership, evidence state, policy-versus-enforcement separation, and consequential human decision authority.', jsonb_build_array('RULE-AUTH-001','RULE-GOV-004','RULE-GP-005','docs/governance/iso/AIMS-SCOPE-DRAFT.md'), 'Retain ownership/accountability mappings and named human assignments as operational evidence matures.')
)
update comind_pm.pm_rule_archaeology_queue q
set metadata = q.metadata || jsonb_build_object(
      'successor_coverage_2026_10_27', jsonb_build_object(
        'assessment_key', 'DRULE-002-SC-001',
        'state', c.coverage_state,
        'rationale', c.rationale,
        'evidence_refs', c.evidence_refs,
        'next_action', c.next_action,
        'source_text_status', 'original_clause_text_missing',
        'archaeology_status_unchanged', true,
        'assessed_at', now()
      )
    ),
    updated_at = now()
from coverage c, source_document s
where q.source_document_id = s.id
  and q.section_number = c.section_number
  and q.section_number between 1 and 28;

with project as (
  select id from comind_pm.pm_projects where project_key = 'COMIND'
), gaps(case_key, section_number, title, severity, problem_statement, resolution_criteria, evidence_refs) as (
  values
  ('RC-L0-GAP-DCLASS-001', 3, 'Close current data classification and tagging governance gap', 'high', 'Historical Layer-0 Section 3 text remains unrecovered, and this successor review separately finds a current governance gap: CoMind recognizes data classification and sensitivity as in scope, while the current AIMS applicability evidence still records gaps in data-resource sensitivity, allowed-use, requirements, and labeling governance. This case tracks the present-day control gap, not recovery of the 2025 wording.', 'Approve a canonical classification taxonomy and handling contract that maps classes or attributes to access, retention, logging, external transfer, deletion, evidence, and enforcement; add deterministic verification where machine-checkable; retain historical-source loss as a separate archaeology fact.', jsonb_build_array(jsonb_build_object('repo','docs/governance/iso/AIMS-STATEMENT-OF-APPLICABILITY-PROVISIONAL.md'),jsonb_build_object('repo','docs/governance/iso/AIMS-SCOPE-DRAFT.md'),jsonb_build_object('source','NIST SP 800-60 Rev. 2 Initial Working Draft','url','https://csrc.nist.gov/pubs/sp/800/60/r2/iwd'))),
  ('RC-L0-GAP-EGRESS-001', 13, 'Close current network and egress governance gap', 'high', 'Historical Layer-0 Section 13 text remains unrecovered, and this successor review separately finds a current governance gap: component-specific network configuration does not provide a canonical cross-system egress and information-flow contract for agents, tools, connectors, services, and data transfers. The current AIMS applicability evidence records compute, storage, network, and execution-environment governance as a gap.', 'Approve a network and egress contract covering service/resource identity, destination authorization, least privilege, outbound information-flow policy, sensitive-data transfer restrictions, logging, exceptions, fail behavior, and test evidence; map provider, connector, browser/server, export, and service-to-service paths to it.', jsonb_build_array(jsonb_build_object('repo','docs/governance/iso/AIMS-STATEMENT-OF-APPLICABILITY-PROVISIONAL.md'),jsonb_build_object('source','NIST SP 800-207','url','https://csrc.nist.gov/pubs/sp/800/207/final'),jsonb_build_object('source','NIST SP 800-207A','url','https://csrc.nist.gov/pubs/sp/800/207/a/final'),jsonb_build_object('source','NIST SP 800-53 AC-4','url','https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final'))),
  ('RC-L0-GAP-TENANCY-001', 17, 'Close current multi-tenancy and isolation governance gap', 'critical', 'Historical Layer-0 Section 17 text remains unrecovered, and this successor review separately finds a current governance gap: cross-tenant/project leakage is recognized as a material risk, tenant-session enforcement remains an outstanding critical item, and current AIMS evidence reports broad database-access/RLS weaknesses. CoMind lacks one canonical end-to-end tenancy-isolation contract.', 'Define tenant/project identity propagation and authorization boundaries across database, services, agents, retrieval, caches, connectors, exports, and background work; require deny-by-default isolation where applicable, cross-tenant negative tests, explicit service-role exceptions, incident evidence, and deployment-specific verification before multi-tenant production claims.', jsonb_build_array(jsonb_build_object('repo','docs/governance/iso/AIMS-RISK-AND-IMPACT-REGISTER.md'),jsonb_build_object('repo','docs/governance/iso/AIMS-CONTROL-EVIDENCE-MATRIX.md'),jsonb_build_object('repo','db/sql/v2/12_enterprise_checklist.sql'),jsonb_build_object('source','Supabase RLS guidance','url','https://supabase.com/docs/guides/database/postgres/row-level-security'),jsonb_build_object('source','NIST SP 800-207A','url','https://csrc.nist.gov/pubs/sp/800/207/a/final')))
)
insert into comind_pm.pm_rule_reconciliation_cases (
  project_id, case_key, case_type, title, status, severity, problem_statement,
  resolution_criteria, authority_owner, opened_by, evidence_refs, metadata
)
select
  p.id, g.case_key, 'source_gap', g.title, 'open', g.severity, g.problem_statement,
  g.resolution_criteria, 'CoMind Governance', 'DRULE-002 successor coverage', g.evidence_refs,
  jsonb_build_object(
    'assessment_key','DRULE-002-SC-001',
    'layer0_section',g.section_number,
    'gap_dimension','modern_governance_control',
    'historical_source_gap_remains_separate',true,
    'opened_at_assessment','2026-10-27'
  )
from project p cross join gaps g
on conflict (project_id, case_key) do update set
  title = excluded.title,
  status = 'open',
  severity = excluded.severity,
  problem_statement = excluded.problem_statement,
  resolution_criteria = excluded.resolution_criteria,
  evidence_refs = excluded.evidence_refs,
  metadata = comind_pm.pm_rule_reconciliation_cases.metadata || excluded.metadata,
  updated_at = now();

commit;
